+/**
+ * performOutbox's outcome write (transactions.ts): the state it reports is the state recorded. When
+ * the done/failed write cannot be made, the record stays performing and the result is "skipped",
+ * so a caller never counts an unrecorded effect as done or failed.
+ */
+import { describe, expect, it } from "vitest";
+import { OUTBOX_COLLECTION, performOutbox, type OutboxRecord } from "../src/transactions.js";
+
+type Row = OutboxRecord & { __version: number };
+
+const RECORD: OutboxRecord = {
+  id: "outbox_inv1_1", requestId: "r1", function: "pay", principalId: "dev",
+  effect: { service: "notifications", method: "send", input: { recipient: "dev", type: "paid", title: "inv1" } },
+  state: "pending", createdAt: 0, updatedAt: 0, attempts: 0
+};
+
+/** An in-memory store whose nth transaction (1 = the claim) fails when `fails(n)`. */
+function store(fails: (n: number) => boolean) {
+  const rows = new Map<string, Row>([[RECORD.id, { ...structuredClone(RECORD), __version: 1 }]]);
+  let writes = 0;
+  return {
+    rows,
+    collection(name: string) {
+      expect(name).toBe(OUTBOX_COLLECTION);
+      return {
+        async get(id: string) { const r = rows.get(id); return r ? structuredClone(r) : null; },
+        async find() { return [...rows.values()].map(r => structuredClone(r)); }
+      };
+    },
+    async transaction(request: { operations: Array<{ id: string; ifVersion: number; value: OutboxRecord }> }) {
+      writes += 1;
+      if (fails(writes)) throw new Error("store unavailable");
+      for (const op of request.operations) {
+        const current = rows.get(op.id);
+        if (!current || current.__version !== op.ifVersion) throw new Error("version conflict");
+        rows.set(op.id, { ...structuredClone(op.value), __version: current.__version + 1 });
+      }
+      return {};
+    }
+  };
+}
+
+describe("performOutbox outcome write", () => {
+  it("does not report done when done could not be recorded", async () => {
+    const db = store(n => n >= 2);
+    const warnings: string[] = [];
+    const outcome = await performOutbox(db as never, RECORD.id, async () => ({ notificationId: "n1" }), m => warnings.push(m));
+    expect(outcome).toBe("skipped");
+    expect(db.rows.get(RECORD.id)!.state).toBe("performing");
+    expect(warnings.length).toBeGreaterThan(0);
+  });
+
+  it("does not report failed when failed could not be recorded", async () => {
+    const db = store(n => n >= 2);
+    const outcome = await performOutbox(db as never, RECORD.id, async () => { throw new Error("boom"); });
+    expect(outcome).toBe("skipped");
+    expect(db.rows.get(RECORD.id)!.state).toBe("performing");
+  });
+
+  it("retries a transiently failed outcome write and records it", async () => {
+    const db = store(n => n === 2);
+    const outcome = await performOutbox(db as never, RECORD.id, async () => ({ notificationId: "n1" }));
+    expect(outcome).toBe("done");
+    expect(db.rows.get(RECORD.id)).toMatchObject({ state: "done", result: { notificationId: "n1" }, attempts: 1 });
+  });
+
+  it("reports done when the outcome is recorded first time", async () => {
+    const db = store(() => false);
+    expect(await performOutbox(db as never, RECORD.id, async () => ({}))).toBe("done");
+    expect(db.rows.get(RECORD.id)!.state).toBe("done");
+  });
+});

data.body:
After the effect runs, performOutbox persists the outcome with a version-guarded put. If that write throws (a version conflict, or any store error), the error is only passed to warn() and the function still returns next.state ('done' or 'failed') as if the outcome had been recorded. The record then stays 'performing' with attempts incremented. Callers rely on the return value: recoverOutbox counts it as performed (host.ts 521-523), and retryOutbox returns the record as its state is now. Meanwhile isRecoverable only picks up a 'performing' record once it is OUTBOX_PERFORMING_STALE_MS (300 s) old. So: (a) an effect that succeeded but whose 'done' could not be written is reported done, then performed a second time about 300 s later. For notifications this depends entirely on the downstream idempotency key. (b) An effect that failed, whose 'failed' could not be written, is reported 'failed' but is silently re-run automatically. That contradicts the documented rule that a failed effect is retried only by an operator. The host sees a success or failure status that does not match durable state.

**Severity:** medium

### Evidence

1. [`packages/appboundry-host/src/transactions.ts` lines 205–210](https://github.com/rkendel1/appboundry/blob/ec75dbd921ef327ea9a2cb9a599beae5d48d6193/packages/appboundry-host/src/transactions.ts#L205-L210):

```
  try {
    await put(db, id, claim.__version, next);
  } catch (error) {
    warn(`after-commit ${id}: could not record ${next.state}: ${(error as Error).message}`);
  }
  return next.state as "done" | "failed";
```

2. [`packages/appboundry-host/src/transactions.ts` lines 139–141](https://github.com/rkendel1/appboundry/blob/ec75dbd921ef327ea9a2cb9a599beae5d48d6193/packages/appboundry-host/src/transactions.ts#L139-L141):

```
export function isRecoverable(record: Pick<OutboxRecord, "state" | "updatedAt">, now: number): boolean {
  return (record.state === "pending" && now - record.updatedAt >= OUTBOX_RECOVER_AFTER_MS) || (record.state === "performing" && now - record.updatedAt >= OUTBOX_PERFORMING_STALE_MS);
}
```

3. [`packages/appboundry-host/src/host.ts` lines 521–523](https://github.com/rkendel1/appboundry/blob/ec75dbd921ef327ea9a2cb9a599beae5d48d6193/packages/appboundry-host/src/host.ts#L521-L523):

```
    for (const record of stale) {
      if ((await this.#performAs(record)) === "done") performed += 1;
    }
```

### Suggested fix

When the outcome put fails, do not return next.state. Re-read the record and return its actual persisted state. If it is still 'performing', return a distinct result such as 'unrecorded' or rethrow, so callers do not count it as done. Also retry the outcome write a bounded number of times on transient errors (re-reading the version) before giving up, so a performed effect is not left eligible for automatic re-execution.

### How this was verified

- packages/appboundry-host/src/transactions.ts:205-210 contains the quoted code
- packages/appboundry-host/src/transactions.ts:139-141 contains the quoted code
- packages/appboundry-host/src/host.ts:521-523 contains the quoted code

Found and verified by Eve2 (task `mwvy5fde3b87b4b4a9b3`, rkendel1/appboundry@ec75dbd921ef): each piece of evidence was re-read or re-run before filing.

