{"path": "packages/appboundry-host/test/outbox-outcome.test.ts", "content": "/**
 * performOutbox's outcome write (transactions.ts): the state it reports is the state recorded. When
 * the done/failed write cannot be made, the record stays performing and the result says so
 * ("unrecorded"), so a caller never counts an unrecorded effect as done or failed.
 */
import { describe, expect, it } from "vitest";
import { OUTBOX_COLLECTION, performOutbox, type OutboxRecord } from "../src/transactions.js";

type Row = OutboxRecord & { __version: number };

const RECORD: OutboxRecord = {
  id: "outbox_inv1_1", requestId: "r1", function: "pay", principalId: "dev",
  effect: { service: "notifications", method: "send", input: { recipient: "dev", type: "paid", title: "inv1" } },
  state: "pending", createdAt: 0, updatedAt: 0, attempts: 0
};

/** An in-memory store whose nth transaction (1 = the claim) fails when `fails(n)`. */
function store(fails: (n: number) => boolean) {
  const rows = new Map<string, Row>([[RECORD.id, { ...structuredClone(RECORD), __version: 1 }]]);
  let writes = 0;
  return {
    rows,
    collection(name: string) {
      expect(name).toBe(OUTBOX_COLLECTION);
      return {
        async get(id: string) { const r = rows.get(id); return r ? structuredClone(r) : null; },
        async find() { return [...rows.values()].map(r => structuredClone(r)); }
      };
    },
    async transaction(request: { operations: Array<{ id: string; ifVersion: number; value: OutboxRecord }> }) {
      writes += 1;
      if (fails(writes)) throw new Error("store unavailable");
      for (const op of request.operations) {
        const current = rows.get(op.id);
        if (!current || current.__version !== op.ifVersion) throw new Error("version conflict");
        rows.set(op.id, { ...structuredClone(op.value), __version: current.__version + 1 });
      }
      return {};
    }
  };
}

describe("performOutbox outcome write", () => {
  it("does not report done when done could not be recorded", async () => {
    const db = store(n => n >= 2);
    const warnings: string[] = [];
    const outcome = await performOutbox(db as never, RECORD.id, async () => ({ notificationId: "n1" }), m => warnings.push(m));
    expect(outcome).toBe("unrecorded");
    expect(db.rows.get(RECORD.id)!.state).toBe("performing");
    expect(warnings.length).toBeGreaterThan(0);
  });

  it("does not report failed when failed could not be recorded", async () => {
    const db = store(n => n >= 2);
    const outcome = await performOutbox(db as never, RECORD.id, async () => { throw new Error("boom"); });
    expect(outcome).toBe("unrecorded");
    expect(db.rows.get(RECORD.id)!.state).toBe("performing");
  });

  it("retries a transiently failed outcome write and records it", async () => {
    const db = store(n => n === 2);
    const outcome = await performOutbox(db as never, RECORD.id, async () => ({ notificationId: "n1" }));
    expect(outcome).toBe("done");
    expect(db.rows.get(RECORD.id)).toMatchObject({ state: "done", result: { notificationId: "n1" }, attempts: 1 });
  });

  it("reports done when the outcome is recorded first time", async () => {
    const db = store(() => false);
    expect(await performOutbox(db as never, RECORD.id, async () => ({}))).toBe("done");
    expect(db.rows.get(RECORD.id)!.state).toBe("done");
  });
});
"}

